UPDATE gm_announce
SET title = 'Thông báo máy chủ Meow 3Q',
    content = 'Kính chào Tiên trưởng!\n\nChào mừng bạn đến với máy chủ trải nghiệm Meow 3Q.\n\n【TRẠNG THÁI MÁY CHỦ】\n- Máy chủ đang hoạt động ổn định.\n- Dữ liệu được lưu tự động trong quá trình chơi.\n- Đây là máy chủ cá nhân phục vụ thử nghiệm và chỉnh sửa game.\n\n【NỘI DUNG TRẢI NGHIỆM】\n1. Xây dựng đội hình và nâng cấp anh hùng.\n2. Trải nghiệm vượt ải, đấu trường, bang hội và các hoạt động giới hạn.\n3. Kiểm tra giao diện, kỹ năng, vật phẩm và nội dung Việt hóa.\n\n【LƯU Ý】\n- Nếu gặp lỗi hiển thị, hãy tải lại trang bằng Ctrl + F5.\n- Một số tính năng cũ có thể đang được tiếp tục hoàn thiện.\n- Hãy chụp lại màn hình khi phát hiện lỗi để việc sửa chữa nhanh và chính xác hơn.\n\nCập nhật ngày 10/08/2026. Chúc bạn chơi game vui vẻ!',
    begin_time = NULL,
    end_time = NULL
WHERE id = 1 AND game_id = '10091';
